//! Counted UTF-8 string and explicit-length Unicode conversion helpers.
//! These routines never allocate; AllocateDestinationString=true is rejected.
use super::{AnsiString,UnicodeString};
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;
#[repr(C)] pub struct Utf8String {pub length:u16,pub maximum_length:u16,pub buffer:*mut u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_init_string_ex(dst:*mut AnsiString,src:*const u8)->i32{if dst.is_null(){return INVALID;}unsafe{super::strings::rtl_init_ansi_string(dst,src);}if !src.is_null()&&unsafe{(*dst).maximum_length==u16::MAX}{INVALID}else{SUCCESS}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_init_utf8_string(dst:*mut Utf8String,src:*const u8){if dst.is_null(){return;}let d=unsafe{&mut *dst};d.buffer=src as *mut u8;if src.is_null(){d.length=0;d.maximum_length=0;return;}let mut n=0usize;while n<u16::MAX as usize-1&&unsafe{*src.add(n)}!=0{n+=1;}d.length=n as u16;d.maximum_length=(n+1) as u16;}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_init_utf8_string_ex(dst:*mut Utf8String,src:*const u8)->i32{if dst.is_null(){return INVALID;}unsafe{rtl_init_utf8_string(dst,src);}if !src.is_null()&&unsafe{(*dst).maximum_length==u16::MAX}{INVALID}else{SUCCESS}}
fn decode_one(s:&[u8],i:usize)->Option<(u32,usize)>{let b=*s.get(i)?;if b<0x80{return Some((b as u32,1));}let (need,mut cp,min)=if b&0xe0==0xc0{(2,(b&0x1f) as u32,0x80)}else if b&0xf0==0xe0{(3,(b&0x0f) as u32,0x800)}else if b&0xf8==0xf0{(4,(b&7) as u32,0x10000)}else{return None;};if i+need>s.len(){return None;}for j in 1..need{let c=s[i+j];if c&0xc0!=0x80{return None;}cp=(cp<<6)|((c&0x3f) as u32);}if cp<min||cp>0x10ffff||(0xd800..=0xdfff).contains(&cp){return None;}Some((cp,need))}
fn encode_one(cp:u32,out:&mut [u8;4])->usize{if cp<0x80{out[0]=cp as u8;1}else if cp<0x800{out[0]=(0xc0|(cp>>6)) as u8;out[1]=(0x80|(cp&63)) as u8;2}else if cp<0x10000{out[0]=(0xe0|(cp>>12)) as u8;out[1]=(0x80|((cp>>6)&63)) as u8;out[2]=(0x80|(cp&63)) as u8;3}else{out[0]=(0xf0|(cp>>18)) as u8;out[1]=(0x80|((cp>>12)&63)) as u8;out[2]=(0x80|((cp>>6)&63)) as u8;out[3]=(0x80|(cp&63)) as u8;4}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_utf8_to_unicode_n(dst:*mut u16,dst_bytes:u32,written:*mut u32,src:*const u8,src_bytes:u32)->i32{
 if written.is_null()||(src_bytes>0&&src.is_null())||(dst_bytes>0&&dst.is_null()){return INVALID;}unsafe{*written=0;}let s=if src_bytes==0{&[][..]}else{unsafe{core::slice::from_raw_parts(src,src_bytes as usize)}};let cap=(dst_bytes/2) as usize;let mut i=0usize;let mut o=0usize;while i<s.len(){let Some((cp,n))=decode_one(s,i)else{return INVALID;};let need=if cp>0xffff{2}else{1};if o+need>cap{unsafe{*written=(o*2) as u32;}return SMALL;}unsafe{if need==1{*dst.add(o)=cp as u16;}else{let x=cp-0x10000;*dst.add(o)=0xd800+((x>>10) as u16);*dst.add(o+1)=0xdc00+((x&0x3ff) as u16);}}o+=need;i+=n;}unsafe{*written=(o*2) as u32;}SUCCESS
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_to_utf8_n(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32)->i32{
 if written.is_null()||src_bytes%2!=0||(src_bytes>0&&src.is_null())||(dst_bytes>0&&dst.is_null()){return INVALID;}unsafe{*written=0;}let n=(src_bytes/2) as usize;let s=if n==0{&[][..]}else{unsafe{core::slice::from_raw_parts(src,n)}};let mut i=0usize;let mut o=0usize;while i<s.len(){let a=s[i] as u32;let (cp,step)=if (0xd800..=0xdbff).contains(&s[i]){if i+1>=s.len()||!(0xdc00..=0xdfff).contains(&s[i+1]){return INVALID;} (0x10000+((a-0xd800)<<10)+(s[i+1] as u32-0xdc00),2)}else if (0xdc00..=0xdfff).contains(&s[i]){return INVALID}else{(a,1)};let mut b=[0u8;4];let k=encode_one(cp,&mut b);if o+k>dst_bytes as usize{unsafe{*written=o as u32;}return SMALL;}unsafe{core::ptr::copy_nonoverlapping(b.as_ptr(),dst.add(o),k);}o+=k;i+=step;}unsafe{*written=o as u32;}SUCCESS
}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_utf8_string_to_unicode_string(dst:*mut UnicodeString,src:*const Utf8String,allocate:u8)->i32{if dst.is_null()||src.is_null()||allocate!=0{return INVALID;}let d=unsafe{&mut *dst};let s=unsafe{&*src};if s.length>0&&s.buffer.is_null(){return INVALID;}let mut written=0u32;let st=unsafe{rtl_utf8_to_unicode_n(d.buffer,d.maximum_length as u32,&mut written,s.buffer,s.length as u32)};if st==SUCCESS{d.length=written as u16;}st}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_string_to_utf8_string(dst:*mut Utf8String,src:*const UnicodeString,allocate:u8)->i32{if dst.is_null()||src.is_null()||allocate!=0{return INVALID;}let d=unsafe{&mut *dst};let s=unsafe{&*src};if s.length%2!=0||(s.length>0&&s.buffer.is_null()){return INVALID;}let mut written=0u32;let st=unsafe{rtl_unicode_to_utf8_n(d.buffer,d.maximum_length as u32,&mut written,s.buffer,s.length as u32)};if st==SUCCESS{if written>u16::MAX as u32{return SMALL;}d.length=written as u16;}st}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_oem_to_unicode_n(dst:*mut u16,dst_bytes:u32,written:*mut u32,src:*const u8,src_bytes:u32)->i32{unsafe{super::misc_extra::rtl_multi_byte_to_unicode_n(dst,dst_bytes,written,src,src_bytes)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_to_oem_n(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32)->i32{unsafe{super::misc_extra::rtl_unicode_to_multi_byte_n(dst,dst_bytes,written,src,src_bytes)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_upcase_unicode_to_oem_n(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32)->i32{if src_bytes%2!=0||(src_bytes>0&&src.is_null()){return INVALID;}let n=(src_bytes/2) as usize;if written.is_null()||(dst_bytes>0&&dst.is_null()){return INVALID;}let k=n.min(dst_bytes as usize);for i in 0..k{let mut c=unsafe{*src.add(i)};if (97..=122).contains(&c){c-=32;}unsafe{*dst.add(i)=if c<=255{c as u8}else{b'?'};}}unsafe{*written=k as u32;}if k<n{SMALL}else{SUCCESS}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_upcase_unicode_to_multi_byte_n(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32)->i32{unsafe{rtl_upcase_unicode_to_oem_n(dst,dst_bytes,written,src,src_bytes)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_upcase_unicode_string_to_oem_string(dst:*mut AnsiString,src:*const UnicodeString,allocate:u8)->i32{if dst.is_null()||src.is_null()||allocate!=0{return INVALID;}let d=unsafe{&mut *dst};let s=unsafe{&*src};if s.length%2!=0||(s.length>0&&s.buffer.is_null()){return INVALID;}let n=(s.length/2) as usize;if n>d.maximum_length as usize{return SMALL;}if n>0&&d.buffer.is_null(){return INVALID;}for i in 0..n{let mut c=unsafe{*s.buffer.add(i)};if (97..=122).contains(&c){c-=32;}unsafe{*d.buffer.add(i)=if c<=255{c as u8}else{b'?'};}}d.length=n as u16;SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_upcase_unicode_string_to_counted_oem_string(dst:*mut AnsiString,src:*const UnicodeString,allocate:u8)->i32{unsafe{rtl_upcase_unicode_string_to_oem_string(dst,src,allocate)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_string_to_counted_oem_string(dst:*mut AnsiString,src:*const UnicodeString,allocate:u8)->i32{unsafe{super::conversion_extra::rtl_unicode_string_to_ansi_string(dst,src,allocate)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_oem_string_to_counted_unicode_string(dst:*mut UnicodeString,src:*const AnsiString,allocate:u8)->i32{unsafe{super::conversion_extra::rtl_ansi_string_to_unicode_string(dst,src,allocate)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_oem_string_to_unicode_string(dst:*mut UnicodeString,src:*const AnsiString,allocate:u8)->i32{unsafe{super::conversion_extra::rtl_ansi_string_to_unicode_string(dst,src,allocate)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_string_to_oem_string(dst:*mut AnsiString,src:*const UnicodeString,allocate:u8)->i32{unsafe{super::conversion_extra::rtl_unicode_string_to_ansi_string(dst,src,allocate)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_upcase_unicode_to_custom_cpn(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32,_table:*const core::ffi::c_void)->i32{unsafe{rtl_upcase_unicode_to_oem_n(dst,dst_bytes,written,src,src_bytes)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_unicode_to_custom_cpn(dst:*mut u8,dst_bytes:u32,written:*mut u32,src:*const u16,src_bytes:u32,_table:*const core::ffi::c_void)->i32{unsafe{rtl_unicode_to_oem_n(dst,dst_bytes,written,src,src_bytes)}}
